g_ScnCerebroSpace = -$3B82	; byte: scene id of "CerebroScreen Space" (Scene_RegisterAll)
g_ScnSpaceB1 = -$3B66	; byte: scene id of "SpaceB1 Maintenance_Shaft" (Scene_RegisterAll)
g_ScnSpaceA1 = -$3B68	; byte: scene id of "SpaceA1 Space_Elevator" (Scene_RegisterAll)
g_ScnCerebroClone = -$3B84	; byte: scene id of "CerebroScreen Clone" (Scene_RegisterAll)
g_ScnCloneA1 = -$3B6A	; byte: scene id of "CloneA1 Factory_Floor_1" (Scene_RegisterAll)
